import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u11")
C = "A2-B1"

L(1, "Atender e começar uma chamada", "Met Ana. Hoi, met Pedro! Stoor ik?",
  ["Atender e iniciar chamadas como os neerlandeses"],
  vocab=[V("v-storen","storen","incomodar","verb",note="Stoor ik? = Estou a incomodar?"),
         V("v-bellen-over","bellen over","ligar por causa de","expression"), V("v-uitkomen-nu","komt het nu uit?","dá jeito agora?","expression")],
  ex=[("Met Ana de Vries.","Fala Ana de Vries."),("Hoi, met Pedro! Stoor ik?","Olá, é o Pedro! Estou a incomodar?"),("Ik bel over het feest van zaterdag.","Ligo por causa da festa de sábado."),("Komt het nu uit?","Dá jeito agora?")],
  gram=[G("g-telefoon-nl","Atender com o nome","Os neerlandeses atendem dizendo o próprio nome: **Met Ana** ou só o apelido. Quem liga também se identifica: **Hoi, met Pedro.** Depois é educado perguntar **Stoor ik?** e dizer o motivo: **Ik bel over…**",
    [("Goedemiddag, met Tom Bakker van Bakker Installaties.","Boa tarde, fala Tom Bakker, da Bakker Installaties.")],
    "Em Portugal atende-se com «Estou?» ou «Sim?»; nos Países Baixos isso soa estranho.")],
  review=["v-met-naam","v-bellen","v-spreken-met","v-hallo"],
  cefr=C, exs=[
    MA([("met + nome","fala…"),("storen","incomodar"),("bellen over","ligar por causa de"),("komt het nu uit?","dá jeito agora?")], "Ao telefone.", ["v-met-naam","v-storen","v-bellen-over","v-uitkomen-nu"]),
    MC("O telefone toca. Como atende à neerlandesa?", ["*Met Rita.","Estou?|Não se usa.","Wie ben jij?|Brusco."], "Met + nome.", ["v-met-naam"]),
    TR("pt-nl","Estou a incomodar?", ["Stoor ik"], "storen.", ["v-storen"]),
    TR("pt-nl","Ligo por causa da festa de sábado.", ["Ik bel over het feest van zaterdag","Ik bel over het feestje van zaterdag","Ik bel voor het feest van zaterdag"], "bellen over.", ["v-bellen-over"]),
    TR("nl-pt","Komt het nu uit?", ["Dá jeito agora","Dá-te jeito agora","É boa altura agora"], "uitkomen.", ["v-uitkomen-nu"]),
    CJ("storen","ik","Sorry dat ik ___ .", ["stoor"], "ik stoor.", ["v-storen"]),
    DL([("Sanne","Met Sanne.","Fala a Sanne."),("Rui","")], ["*Hoi Sanne, met Rui. Stoor ik?","Estou? Quem é?|Não é natural em neerlandês.","Met Sanne.|Ela é que é a Sanne."], "Identificar-se.", ["v-met-naam","v-storen"]),
    LI("Goedemiddag, met Tom Bakker.", ["Goedemiddag(,) met Tom Bakker"], "Boa tarde, fala Tom Bakker.", "Fórmula.", ["v-met-naam"]),
    FB("Ik bel ___ je verjaardag.", ["over"], "bellen over.", ["v-bellen-over"], choices=["over","van","met"], tr="Ligo por causa do teu aniversário."),
    WO("Desculpa incomodar.", ["Sorry","dat","ik","stoor"], "dat + verbo no fim.", ["v-storen"]),
  ], diff=3, mins=6)

L(2, "Não percebi: pedir para repetir", "Sorry, de verbinding is slecht. Kunt u dat spellen?",
  ["Lidar com problemas de compreensão ao telefone"],
  vocab=[V("v-verbinding","verbinding","ligação (rede)","noun","de"), V("v-verstaan","verstaan","ouvir/perceber (som)","verb",note="Ik versta u niet goed."),
         V("v-harder","harder","mais alto","adverb"), V("v-wegvallen","wegvallen","ir-se abaixo (a ligação)","verb",note="Je viel even weg.")],
  ex=[("De verbinding is slecht.","A ligação está má."),("Ik versta u niet goed.","Não o estou a ouvir bem."),("Kunt u iets harder praten?","Pode falar um pouco mais alto?"),("Je viel even weg.","A chamada foi-se abaixo por momentos.")],
  gram=[G("g-verstaan-begrijpen","Verstaan vs. begrijpen","**verstaan** = ouvir/perceber as palavras (som): *Ik versta je niet, het is te druk.* **begrijpen** = compreender o sentido: *Ik begrijp niet wat je bedoelt.*",
    [("Ik versta het wel, maar ik begrijp het niet.","Ouço bem, mas não percebo.")],
    "Em português dizemos «não percebo» nos dois casos.")],
  review=["v-herhalen","v-langzaam","v-spellen","v-begrijpen"],
  cefr=C, exs=[
    MA([("verbinding","ligação"),("verstaan","ouvir/perceber"),("harder","mais alto"),("wegvallen","ir-se abaixo")], "Problemas na chamada.", ["v-verbinding","v-verstaan","v-harder","v-wegvallen"]),
    TR("pt-nl","Não o estou a ouvir bem.", ["Ik versta u niet goed"], "verstaan.", ["v-verstaan"]),
    TR("pt-nl","Pode falar um pouco mais alto?", ["Kunt u iets harder praten","Kunt u wat harder praten","Kunt u iets harder spreken"], "harder.", ["v-harder"]),
    TR("nl-pt","Je viel even weg.", ["A chamada foi-se abaixo por momentos","Falhaste por momentos","Deixei de te ouvir por um momento"], "wegvallen.", ["v-wegvallen"]),
    MC("Há muito barulho e não ouve as palavras. Diz…", ["*Ik versta je niet.","Ik begrijp je niet.|Isso sugere que não percebe o sentido.","Ik ken je niet.|Isso é «não te conheço»."], "verstaan = som.", ["v-verstaan"]),
    AR("verbinding","a ligação","de", "-ing → de.", ["v-verbinding"]),
    FE(["Ik","versta","niet","wat","je","bedoelt."], 1, "begrijp", "Sentido → begrijpen: Ik begrijp niet wat je bedoelt.", ["v-verstaan"]),
    LI("Kunt u uw achternaam even spellen?", ["Kunt u uw achternaam even spellen"], "Pode soletrar o seu apelido?", "spellen.", ["v-spellen"]),
    DL([("Klantenservice","…en dan moet u op de link kl… klikken.","…e depois tem de car… carregar no link."),("Cliente","")], ["*Sorry, de verbinding is slecht. Kunt u dat herhalen?","Ja, prima.|Não ouviu bem — devia pedir para repetir.","Ik ben de link.|Não faz sentido."], "Pedir repetição.", ["v-verbinding","v-herhalen"]),
    FB("Sorry, je viel even ___.", ["weg"], "wegvallen.", ["v-wegvallen"], choices=["weg","uit","af"], tr="Desculpa, a chamada foi-se abaixo por momentos."),
  ], diff=3, mins=6)

L(3, "Deixar recado no voicemail", "U spreekt met de voicemail van… Wilt u mij terugbellen?",
  ["Compreender e deixar mensagens de voz"],
  vocab=[V("v-voicemail","voicemail","correio de voz","noun","de"), V("v-na-de-piep","na de piep","depois do sinal","expression"),
         V("v-zo-snel-mogelijk","zo snel mogelijk","o mais depressa possível","expression")],
  ex=[("U spreekt met de voicemail van Lisa.","Está a falar para o correio de voz da Lisa."),("Spreek een bericht in na de piep.","Deixe mensagem depois do sinal."),("Wilt u mij zo snel mogelijk terugbellen?","Pode ligar-me de volta o mais depressa possível?"),("Mijn nummer is 06 12 34 56 78.","O meu número é 06 12 34 56 78.")],
  review=["v-doorgeven","v-terugbellen","v-bericht-achterlaten","v-telefoonnummer","v-bereikbaar"],
  cefr=C, exs=[
    MA([("voicemail","correio de voz"),("na de piep","depois do sinal"),("zo snel mogelijk","o mais depressa possível"),("doorgeven","transmitir")], "Voicemail.", ["v-voicemail","v-na-de-piep","v-zo-snel-mogelijk","v-doorgeven"]),
    TR("pt-nl","Pode ligar-me de volta o mais depressa possível?", ["Wilt u mij zo snel mogelijk terugbellen","Kunt u mij zo snel mogelijk terugbellen","Wil je me zo snel mogelijk terugbellen"], "zo snel mogelijk.", ["v-zo-snel-mogelijk"]),
    TR("nl-pt","Spreek een bericht in na de piep.", ["Deixe (uma) mensagem depois do sinal","Deixe mensagem após o sinal"], "na de piep.", ["v-na-de-piep"]),
    MC("Os números de telemóvel neerlandeses começam por…", ["*06","+351|Isso é Portugal.","112|Isso é o número de emergência."], "06 …", []),
    CO("text","Voicemail", "Hallo, u spreekt met Mark Visser van garage De Ster. Ik bel over uw auto. De reparatie is klaar, u kunt hem morgen na tien uur ophalen. Heeft u vragen? Bel me even terug op 030 123 45 67. Fijne dag!",
       [("Porque liga o Mark?", ["*O carro está pronto","O carro precisa de peças","Para marcar uma revisão"]),("Quando pode buscar o carro?", ["*Amanhã depois das 10h","Hoje","Na segunda-feira"])],
       "ophalen = ir buscar.", ["v-voicemail"]),
    WO("Deixe mensagem depois do sinal.", ["Spreek","een","bericht","in","na","de","piep"], "inspreken (separável).", ["v-na-de-piep"]),
    LI("Kunt u dat bericht aan haar doorgeven?", ["Kunt u dat bericht aan haar doorgeven"], "Pode passar-lhe essa mensagem?", "doorgeven.", ["v-doorgeven"]),
    FB("Bel me zo ___ mogelijk terug.", ["snel"], "zo snel mogelijk.", ["v-zo-snel-mogelijk"], choices=["snel","sneller","snelste"], tr="Liga-me de volta o mais depressa possível."),
    AR("voicemail","o correio de voz","de", "De voicemail.", ["v-voicemail"]),
    SW("Deixe uma mensagem de voz (por escrito): diga quem é, porque liga e peça para lhe ligarem de volta.", ["Hallo, met Ana Costa. Ik bel over de afspraak van vrijdag. Wilt u mij terugbellen op 06 12345678? Dank u wel!"], ["Identificou-se (**met …**)", "Motivo (**ik bel over…**)", "Pedido de **terugbellen** + número"], 15, "Mensagem de voz.", ["v-zo-snel-mogelijk"]),
  ], diff=3, mins=7)

L(4, "Mensagens escritas (app)", "Ben er over 5 min! Top! Kun je even bellen?",
  ["Ler e escrever mensagens informais curtas"],
  vocab=[V("v-appen","appen","mandar mensagem (app)","verb",note="Ik app je straks."), V("v-top","top!","ótimo!","expression"),
         V("v-ben-er-zo","ben er zo","chego já","expression"), V("v-ff","ff","(abrev.) even = um momento","expression"),
         V("v-groetjes-msg","gr. / groetjes","beijinhos|abraço (mensagens)","expression")],
  ex=[("Ik app je straks!","Mando-te mensagem daqui a pouco!"),("Ben er zo!","Chego já!"),("Kun je ff bellen?","Podes ligar num instante?"),("Top, tot zo!","Ótimo, até já!")],
  gram=[G("g-appjes","Linguagem das mensagens","Nas mensagens omite-se muitas vezes o sujeito (*Ben er zo* = Ik ben er zo) e usam-se abreviaturas: **ff** (even), **idd** (inderdaad), **wss** (waarschijnlijk), **gr** (groetjes), **hb** (heb). Só para contextos informais!",
    [("Idd, ff wachten.","Pois é, espera um bocadinho.")])],
  review=["v-tot-straks","v-straks","v-even"],
  cefr=C, exs=[
    MA([("appen","mandar mensagem"),("top!","ótimo!"),("ben er zo","chego já"),("ff","um momento")], "Mensagens.", ["v-appen","v-top","v-ben-er-zo","v-ff"]),
    MA([("idd","inderdaad"),("wss","waarschijnlijk"),("gr","groetjes")], "Abreviaturas.", ["v-groetjes-msg"]),
    TR("pt-nl","Mando-te mensagem daqui a pouco!", ["Ik app je straks","Ik app jou straks","Ik stuur je straks een bericht"], "appen.", ["v-appen"]),
    TR("nl-pt","Ben er zo!", ["Chego já","Estou quase a chegar","Já aí estou"], "Sujeito omitido.", ["v-ben-er-zo"]),
    MC("«Ff» numa mensagem significa…", ["*even (um momento)","favor|Não.","fijn feest|Não."], "ff = even.", ["v-ff"]),
    MC("Onde NÃO deve usar «ff» e «idd»?", ["*Num e-mail ao chefe ou a uma empresa","Numa mensagem a um amigo|Aí é normal.","No grupo da família|Aí é normal."], "Registo.", ["v-ff"]),
    CJ("appen","ik","Ik ___ je vanavond.", ["app"], "ik app.", ["v-appen"]),
    LI("Top, tot zo!", ["Top(,) tot zo"], "Ótimo, até já!", "top.", ["v-top"]),
    CO("dialogue","Groepsapp", "Lotte: Wie gaat er mee naar de markt? 🍓\nDaan: Ik! Hoe laat?\nLotte: 10u bij de kerk\nPedro: Kan pas om half 11, sorry. Ben er wss rond 11\nLotte: Top, we wachten ff bij de koffiekar ☕",
       [("Quando chega o Pedro?", ["*Provavelmente por volta das 11","Às 10","Não vem"]),("Onde esperam?", ["*Junto à banca do café","Na igreja","Em casa da Lotte"])],
       "wss = waarschijnlijk; koffiekar = carrinho de café.", ["v-ff","v-top"]),
    SW("Responda a «Heb je zin om vanavond te eten?» com uma mensagem curta e informal a aceitar e dizer a hora.", ["Ja top! Ben er om 7 uur. Zal ik iets meenemen?"], ["Tom informal", "Aceitou (**top / leuk**)", "Disse a hora"], 6, "Mensagem informal.", ["v-top","v-appen"]),
  ], diff=3, mins=6)

L(5, "Marcar por telefone", "Ik wil graag een afspraak maken. Schikt dinsdag om tien uur?",
  ["Fazer uma marcação por telefone do início ao fim"],
  vocab=[V("v-plek-vrij","er is plek","há vaga|há disponibilidade","expression"), V("v-volgeboekt","volgeboekt","sem vagas|esgotado","adjective"),
         V("v-genoteerd","genoteerd","anotado","adjective"), V("v-herinnering-sms","herinneringssms","SMS de lembrete","noun","de")],
  ex=[("Is er dinsdag nog plek?","Ainda há vaga na terça?"),("Donderdag zijn we helaas volgeboekt.","Infelizmente na quinta estamos sem vagas."),("Ik heb het genoteerd.","Ficou anotado."),("U krijgt een dag van tevoren een herinneringssms.","Recebe um SMS de lembrete na véspera.")],
  review=["v-afspraak-maken","v-schikken","v-uitkomen-goed","v-op-naam-van"],
  cefr=C, exs=[
    MA([("er is plek","há vaga"),("volgeboekt","sem vagas"),("genoteerd","anotado"),("herinneringssms","SMS de lembrete")], "Marcações.", ["v-plek-vrij","v-volgeboekt","v-genoteerd","v-herinnering-sms"]),
    TR("pt-nl","Ainda há vaga na terça?", ["Is er dinsdag nog plek","Is er op dinsdag nog plek","Heeft u dinsdag nog plek"], "plek.", ["v-plek-vrij"]),
    TR("nl-pt","Donderdag zijn we helaas volgeboekt.", ["Infelizmente na quinta estamos [sem vagas|cheios|lotados]"], "volgeboekt.", ["v-volgeboekt"]),
    TR("nl-pt","Ik heb het genoteerd.", ["Ficou anotado","Já anotei","Tomei nota"], "genoteerd.", ["v-genoteerd"]),
    CO("dialogue","Bij de kapper", "Kapper: Kapsalon Knip, met Esra.\nMiguel: Goedemorgen, met Miguel Santos. Ik wil graag een afspraak maken om te knippen.\nKapper: Wanneer komt het u uit?\nMiguel: Zaterdagochtend?\nKapper: Zaterdag zijn we volgeboekt. Vrijdag om vier uur is er nog plek.\nMiguel: Dat is prima.\nKapper: Op welke naam? … Genoteerd. U krijgt een herinneringssms.",
       [("Porque não pode ser sábado?", ["*Está tudo marcado","O salão está fechado","A Esra está doente"]),("Quando fica a marcação?", ["*Sexta às quatro","Sábado de manhã","Sexta de manhã"])],
       "knippen = cortar o cabelo.", ["v-volgeboekt","v-plek-vrij"]),
    WO("Quando é que lhe dá jeito?", ["Wanneer","komt","het","u","uit?"], "uitkomen.", ["v-uitkomen-goed"]),
    LI("Op welke naam mag ik de afspraak zetten?", ["Op welke naam mag ik de afspraak zetten"], "Em nome de quem marco?", "op naam van.", ["v-op-naam-van"]),
    FB("Sorry, die dag zijn we ___.", ["volgeboekt"], "Sem vagas.", ["v-volgeboekt"], choices=["volgeboekt","genoteerd","plek"], tr="Desculpe, nesse dia estamos sem vagas."),
    DL([("Receptie","Woensdag om half drie, komt dat uit?","Quarta às duas e meia, dá jeito?"),("Cliente","")], ["*Ja, dat komt goed uit. Dank u wel.","Ja, ik kom uit Portugal.|Confusão com «uitkomen».","Nee, ik ben volgeboekt.|Expressão de quem marca."], "Confirmar.", ["v-uitkomen-goed"]),
    MC("Antes de desligar, é útil…", ["*confirmar o dia e a hora","perguntar a idade do rececionista|Não.","desligar sem dizer nada|Não."], "Herhalen = confirmar.", ["v-genoteerd"]),
  ], diff=3, mins=7)

W()
